100	function makeControlledFetch(calls) {
101	  return (url, options) => new Promise((resolve, reject) => {
102	    const call = {
103	      url, options, jsonCalls: 0,
104	      resolveWith: (response) => resolve(response),
105	      resolve(status, body) {
106	        resolve({ status, json: () => { call.jsonCalls += 1; return Promise.resolve(body); } });
107	      },
108	      resolveBadJson(status) {
109	        resolve({
110	          status,
111	          json: () => { call.jsonCalls += 1; return Promise.reject(new SyntaxError('bad json')); },
112	        });
113	      },
114	      reject() { reject(new TypeError('fetch failed')); },
115	    };
116	    calls.push(call);
117	  });
