124	export function loadPage({ fetchImpl } = {}) {
125	  const calls = [];
126	  const byId = buildElements();
127	  const document = buildDocument(byId);
128	  const fetch = fetchImpl ?? makeControlledFetch(calls);
129	  const source = readFileSync(APP_URL, 'utf8');
130	  const context = vm.createContext({ document, fetch });
131	  vm.runInContext(source, context, { filename: 'app.js' });
132	  return { document, el: (id) => byId.get(id), calls, flush };
133	}
