  test('title with surrounding spaces is shown unchanged', async () => {
    const { calls, el, flush } = loadPage();
    calls[1].resolve(200, { bookings: [{ ...B2, title: '  x  ' }] });
    await flush();
    assert.equal(el('booking-list').childNodes[0].childNodes[0].data,
