    await changeFilter(page, '2026-11-05');
    page.calls[2].resolve(200, { bookings: [X] });
    await page.flush();
    page.calls[1].resolve(500, { error: 'late' });
    await page.flush();
    assert.equal(page.el('error').textContent, '');
    assert.deepEqual(texts(page), [X_TEXT]);
